self.KB_CONTENT["card:728057"]={"id":"card:728057","ty":"card","sourceId":"728057","title":"建立BOM變更時，出現“欲新增的元件品號已存在!”，要怎麼處理？","ver":"GP4X","topic":"品號","keywords":["品號","元件","重複","一次"],"y":"error","answer":"因要新增的元件品號，已存在於BOM裡，所以不需再新增一次重複的資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
