self.KB_CONTENT["card:780712"]={"id":"card:780712","ty":"card","sourceId":"780712","title":"『自動產生現金流量表調整沖銷分錄作業』的作業目的為何？","ver":"GP4以上","topic":"科目","keywords":["科目","分錄","透過","沖銷"],"y":"explain","answer":"將調整沖銷分錄樣板設定作業(FCSI15)中所設定的分錄，加上子母公司資料(FCSI02)設定之對應沖銷科目，透過此作業將沖銷分錄產生至現金流量表調整沖銷分錄維護作業(FCSI16)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
