self.KB_CONTENT["card:755992"]={"id":"card:755992","ty":"card","sourceId":"755992","title":"『銷貨單憑證』中的『選擇列印狀態』為何？","ver":"iGP","topic":"銷貨單","keywords":["銷貨單","憑證","狀態"],"y":"other","answer":"* 分為Y.已列印,N.未列印及全部三種.","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
