self.KB_CONTENT["card:772047"]={"id":"card:772047","ty":"card","sourceId":"772047","title":"『專案人工傳票產生/還原作業-EPMB29』【工程帳務方式】中1.完工比例法、5.成本回收法、0.IFRS 15完工比例法，這三類科目綁在一起了，如何拆不同【工程帳務方式】對應不同科目？","ver":"GP4.X","topic":"epmi","keywords":["epmi","科目","傳票","分類"],"y":"howto","answer":"請在『交易對象分類建立作業-EPMI41』設定【分類方式】為'G':專案帳務類型的不同代號之立相關科目後，再至『專案代號建立作業-EPMI14』設定【專案帳務類型】對應的代號，即可不同的專案設定不同的科目，後續執行『專案人工傳票產生/還原作業-EPMB29』時優先取專案代號設定的專案帳務類型代號之科目。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
