self.KB_CONTENT["field:792096"]={"id":"field:792096","ty":"field","sourceId":"792096","title":"匯率","ver":"GP4以上","topic":"","keywords":[],"job":"出貨通知單建立作業","code":"TA023","answer":"* 當期幣別匯率。* 預設對應日期幣別之匯率，可作修改。點選(icon)或[F2]幣別匯率查詢。* 所輸入之匯率必須大於零。","file":"fields.jsonl"};
